function storeImportPreview(){
 if(!stagedStoreImport)return '';
 const {plan}=stagedStoreImport,changed=plan.entries.filter(e=>e.operation!=='변경 없음').length;
 return `<section class="upload-review"><h2>매장 일괄 등록 미리보기</h2><p class="muted">신규 ${plan.entries.filter(e=>e.operation==='신규').length} · 수정 ${plan.entries.filter(e=>e.operation==='수정').length} · 변경 없음 ${plan.entries.filter(e=>e.operation==='변경 없음').length}</p>${plan.newGroups.length?`<p>함께 생성할 관리그룹: ${plan.newGroups.map(esc).join(', ')}</p>`:''}${plan.errors.length?`<div class="import-errors" role="alert">오류 ${plan.errors.length}건 · 저장되지 않았습니다.<ul>${plan.errors.slice(0,50).map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}<div class="table-wrap"><table><thead><tr><th>엑셀 행</th><th>처리</th><th>매장코드</th><th>매장명 (기존 → 적용)</th><th>관리그룹 (기존 → 적용)</th><th>사용상태 (기존 → 적용)</th></tr></thead><tbody>${plan.entries.slice(0,100).map(e=>`<tr><td>${e.row}</td><td>${e.operation}</td><td>${esc(e.code)}</td><td>${e.before?esc(e.before.name)+' → ':''}${esc(e.name)}</td><td>${e.before?esc(e.before.groupName)+' → ':''}${esc(e.groupName)}</td><td>${e.before?(e.before.active?'사용':'사용 제외')+' → ':''}${e.active?'사용':'사용 제외'}</td></tr>`).join('')}</tbody></table></div><p class="muted">미리보기는 최대 100행이며 저장은 검증된 전체 행에 적용합니다. 기존 ID·과거 비용은 보존하고 파일에 없는 매장은 삭제하지 않습니다.</p><p id="store-import-error" class="settings-error" role="alert"></p><div class="toolbar"><button id="store-import-save" class="primary" ${plan.errors.length||!changed?'disabled':''}>검토한 매장 일괄 저장</button><button id="store-import-cancel">취소</button></div></section>`;
}
function bindStoreImport(){
 $('#store-template').onclick=async()=>{try{const wb=await buildStoreImportTemplate(window.ExcelJS,state);downloadBlob('매장마스터_일괄등록.xlsx',new Blob([await wb.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));}catch(error){$('#store-error').textContent=error.message;}};
 $('#store-upload').onclick=()=>$('#store-file').click();
 $('#store-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('파일 크기는 10MB 이하로 업로드하세요.');let lines;if(file.name.toLowerCase().endsWith('.xlsx')){const wb=new window.ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());lines=storeWorkbookLines(wb);}else if(file.name.toLowerCase().endsWith('.csv'))lines=parseCSV((await file.text()).replace(/^\uFEFF/,''));else throw Error('xlsx 또는 CSV 파일을 선택하세요.');const allowNewGroups=$('#store-new-groups').checked;stagedStoreImport={lines,allowNewGroups,plan:planStoreImport(lines,state,{allowNewGroups})};render();}catch(error){stagedStoreImport=null;$('#store-import-preview').innerHTML='';$('#store-error').textContent=error.message;}};
 $('#store-new-groups').onchange=e=>{if(stagedStoreImport){stagedStoreImport.allowNewGroups=e.target.checked;stagedStoreImport.plan=planStoreImport(stagedStoreImport.lines,state,{allowNewGroups:e.target.checked});render();}};
 if($('#store-import-cancel'))$('#store-import-cancel').onclick=()=>{stagedStoreImport=null;render();};
 if($('#store-import-save'))$('#store-import-save').onclick=async e=>{e.target.disabled=true;try{const next=applyStoreImport(stagedStoreImport.plan,state);await saveNext(next);stagedStoreImport=null;refreshScopeFilters();render();toast('매장 마스터 일괄 등록을 완료했습니다.');}catch(error){$('#store-import-error').textContent=error.message;e.target.disabled=false;}};
}

function selectedSales(){return sortSalesRows((state.sales||[]).filter(r=>selectedMonths().includes(r.month)&&scopeMatch(r)),{key:salesOptions.sortKey,direction:salesOptions.sortDirection},state);}
function salesView(){
 const data=selectedSales();if(stagedSalesDelete&&!stagedSalesDelete.rows.every(row=>data.some(r=>r.id===row.id)))stagedSalesDelete=null;for(const id of salesSelection)if(!data.some(r=>r.id===id))salesSelection.delete(id);const writable=['admin','editor'].includes(session.user.role),legacy=state.activity.filter(r=>selectedMonths().includes(r.month)&&scopeMatch(r));
 return `<section class="card panel"><div class="panel-head"><div><h2>ERP 매출 등록 · 조회</h2><div class="sub">월·매장별 매출 집계 · 판매수량은 출고 건수에 포함하지 않습니다.</div></div><span class="badge">${data.length}개 월·매장</span></div><div class="notice">ERP 매출 원장의 매출일자·매장코드·매장명과 선택한 매출 열을 읽어 월·매장별로 합산합니다. 매장코드를 기준으로 매장 마스터와 연결합니다. ERP의 매장명이 달라도 등록할 수 있으며 이름 차이는 미리보기에 안내하고 마스터 이름으로 표시합니다. 이 화면은 조회 월과 관리그룹·매장 필터만 적용합니다. 센터·국가·업무에는 매출을 임의 배분하지 않으므로 해당 범위를 좁힌 대시보드에서는 ERP 매출 기반 물류비율을 표시하지 않습니다.</div><div class="toolbar sales-toolbar"><label>매출 기준<select id="sales-basis">${salesBases.map(b=>`<option ${b===salesOptions.basis?'selected':''}>${b}</option>`).join('')}</select></label><button id="sales-template">매출 양식 다운로드</button><button id="sales-upload" class="primary">ERP 매출 엑셀 업로드</button><input type="file" id="sales-file" accept=".xlsx,.csv" hidden></div><p class="muted">선택한 매출 열을 그대로 합산합니다. 부가세를 자동으로 더하거나 빼지 않습니다. 같은 월·매장 재업로드는 기존 금액을 교체하므로 해당 월·매장의 전체 원장을 사용하세요.</p><p id="sales-error" class="settings-error" role="alert"></p><div id="sales-preview">${salesPreview()}</div><div id="sales-delete-preview">${salesDeletePreview()}</div><div class="scope-summary"><span>선택 범위 ERP 매출</span><strong id="sales-total">₩${money(data.reduce((n,r)=>n+r.amount,0))}</strong></div><p class="muted sales-sort-help">열 제목을 클릭하면 오름차순·내림차순으로 정렬됩니다.</p><div class="toolbar">${writable?`<button id="sales-delete-selected" class="danger-button" ${salesSelection.size?'':'disabled'}>선택 매출 삭제 (${salesSelection.size})</button><span class="muted">선택은 현재 조회 결과에만 적용됩니다.</span>`:''}</div><div class="table-wrap"><table><thead><tr>${writable?'<th><input type="checkbox" id="sales-select-all" aria-label="현재 조회 매출 전체 선택"></th>':''}${salesSortHeader('month','월')}${salesSortHeader('storeCode','매장코드')}${salesSortHeader('storeName','매장명')}${salesSortHeader('groupName','등록 당시 관리그룹')}${salesSortHeader('basis','매출 기준')}${salesSortHeader('sourceRows','ERP 원장 행 수')}${salesSortHeader('amount','매출 (KRW)')}${writable?'<th>관리</th>':''}</tr></thead><tbody>${data.map(r=>`<tr data-sales-id="${esc(r.id)}">${writable?`<td><input type="checkbox" data-sales-select="${esc(r.id)}" aria-label="${esc(r.month+' '+storeCode(r.storeId)+' 매출 선택')}" ${salesSelection.has(r.id)?'checked':''}></td>`:''}<td>${r.month}</td><td>${esc(storeCode(r.storeId))}</td><td>${esc(storeName(r.storeId))}</td><td>${esc(groupName(r.groupId))}</td><td>${r.basis}</td><td>${r.sourceRows}</td><td>₩${money(r.amount)}</td>${writable?`<td><button data-sales-delete="${esc(r.id)}" class="danger-button">삭제</button></td>`:''}</tr>`).join('')}</tbody></table>${data.length?'':'<div class="empty">선택 범위에 ERP 매출이 없습니다. 파일을 업로드한 뒤 미리보기를 확인하세요.</div>'}</div>${legacy.length?`<details class="legacy-sales"><summary>기존 센터별 매출 자료 ${legacy.length}건 (보존)</summary><p class="muted">기존 별도 물동량 값은 출고량 KPI에서 제외합니다. ERP 매출이 한 건이라도 등록된 월은 기존 센터별 매출 전체를 분모에서 제외하고 ERP 매출만 사용합니다. 해당 월의 모든 매장 자료를 준비하세요.</p><div class="table-wrap"><table><thead><tr><th>월</th><th>센터</th><th>매장</th><th>매출</th><th>집계 상태</th></tr></thead><tbody>${legacy.map(r=>`<tr><td>${r.month}</td><td>${esc(r.center)}</td><td>${esc(storeName(r.storeId))}</td><td>₩${money(r.sales)}</td><td>${(state.sales||[]).some(s=>s.month===r.month)?'ERP 매출로 대체 (합산 제외)':'기존 매출 사용'}</td></tr>`).join('')}</tbody></table></div></details>`:''}</section>`;
}
function salesPreview(){
 if(!stagedSales)return '';const {plan}=stagedSales,changed=plan.entries.some(e=>e.operation!=='변경 없음');
 return `<section class="upload-review"><h2>ERP 매출 업로드 미리보기</h2><p>${plan.sourceRows}개 원장 행 → ${plan.entries.length}개 월·매장 집계 · 기준 ${esc(plan.basis)}</p>${plan.errors.length?`<div class="import-errors" role="alert"><b>오류가 있어 저장할 수 없습니다.</b><ul>${plan.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}${plan.warnings.map(w=>`<p class="muted">${esc(w)}</p>`).join('')}<div class="table-wrap"><table><thead><tr><th>처리</th><th>월</th><th>매장코드</th><th>매장</th><th>관리그룹</th><th>원장 행 수</th><th>기존 매출</th><th>적용 매출</th></tr></thead><tbody>${plan.entries.slice(0,100).map(e=>`<tr><td>${e.operation}</td><td>${e.month}</td><td>${esc(storeCode(e.storeId))}</td><td>${esc(storeName(e.storeId))}</td><td>${esc(groupName(e.groupId))}</td><td>${e.sourceRows}</td><td>${e.previousAmount===null?'—':'₩'+money(e.previousAmount)}</td><td>₩${money(e.amount)}</td></tr>`).join('')}</tbody></table></div><p class="muted">미리보기는 최대 100개 집계이며 저장은 검증된 전체 자료에 적용합니다. 파일에 없는 월·매장 매출은 그대로 유지합니다.</p><label class="sales-confirm"><input type="checkbox" id="sales-confirm"> 동일 월·매장은 기존 매출을 교체하며, 파일이 해당 월·매장의 전체 원장임을 확인했습니다.</label><p id="sales-save-error" class="settings-error" role="alert"></p><div class="toolbar"><button id="sales-save" class="primary" disabled>검토한 매출 저장</button><button id="sales-cancel">취소</button></div>${!changed&&!plan.errors.length?'<p class="muted">기존 자료와 동일하여 추가 저장하지 않습니다.</p>':''}</section>`;
}
function bindSales(){
 document.querySelectorAll('[data-sales-sort]').forEach(button=>button.onclick=()=>{const key=button.dataset.salesSort;salesOptions.sortDirection=key===salesOptions.sortKey?(salesOptions.sortDirection==='asc'?'desc':'asc'):(['amount','sourceRows'].includes(key)?'desc':'asc');salesOptions.sortKey=key;render();});
 bindSalesDeletion();
 $('#sales-basis').onchange=e=>{salesOptions.basis=e.target.value;stagedSales=null;render();};$('#sales-upload').onclick=()=>$('#sales-file').click();
 $('#sales-template').onclick=async()=>{try{const wb=await buildSalesTemplate(window.ExcelJS);downloadBlob('ERP매출_입력양식.xlsx',new Blob([await wb.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));}catch(e){$('#sales-error').textContent=e.message;}};
 $('#sales-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('10MB 이하 파일을 사용하세요.');let lines;if(file.name.toLowerCase().endsWith('.xlsx')){const wb=new window.ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());lines=salesWorkbookLines(wb,salesOptions.basis);}else if(file.name.toLowerCase().endsWith('.csv'))lines=parseCSV((await file.text()).replace(/^\uFEFF/,''));else throw Error('XLSX 또는 UTF-8 CSV 파일을 사용하세요.');stagedSales={plan:planSalesImport(lines,state,{basis:salesOptions.basis,fileName:file.name})};render();}catch(error){stagedSales=null;$('#sales-preview').innerHTML='';$('#sales-error').textContent=error.message;}};
 if($('#sales-cancel'))$('#sales-cancel').onclick=()=>{stagedSales=null;render();};
 if($('#sales-confirm'))$('#sales-confirm').onchange=e=>{$('#sales-save').disabled=!e.target.checked||stagedSales.plan.errors.length>0||!stagedSales.plan.entries.some(r=>r.operation!=='변경 없음');};
 if($('#sales-save'))$('#sales-save').onclick=async e=>{if(!$('#sales-confirm').checked)return;e.target.disabled=true;try{const next=applySalesImport(stagedSales.plan,state);await saveNext(next);stagedSales=null;stagedSalesDelete=null;salesSelection.clear();updateMonths();refreshScopeFilters();render();toast('월·매장별 ERP 매출을 저장했습니다. 출고 건수는 변경하지 않았습니다.');}catch(error){$('#sales-save-error').textContent=error.message;}};
}
function exportSales(){const data=selectedSales();download('ERP매출_월매장별.csv',[['월','매장코드','매장명','관리그룹','매출기준','매출','원장행수'],...data.map(r=>[r.month,storeCode(r.storeId),storeName(r.storeId),groupName(r.groupId),r.basis,r.amount,r.sourceRows])].map(r=>r.map(csvCell).join(',')).join('\n'));}

function salesDeletePreview(){
 if(!stagedSalesDelete)return '';const {rows}=stagedSalesDelete;
 return `<section class="upload-review sales-delete-review"><h2>매출 삭제 확인</h2><p>선택한 월·매장별 ERP 매출 <b>${rows.length}건</b> · 합계 <b>₩${money(rows.reduce((n,r)=>n+r.amount,0))}</b></p><div class="table-wrap"><table><thead><tr><th>월</th><th>매장코드</th><th>매장명</th><th>관리그룹</th><th>매출</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.month}</td><td>${esc(storeCode(r.storeId))}</td><td>${esc(storeName(r.storeId))}</td><td>${esc(groupName(r.groupId))}</td><td>₩${money(r.amount)}</td></tr>`).join('')}</tbody></table></div><p class="muted">이 월·매장의 집계 매출을 삭제합니다. 매장 마스터·청구 비용·출고 건수는 삭제하지 않습니다. 같은 월의 ERP 매출을 모두 삭제하면 보존된 기존 센터별 매출이 KPI에 다시 사용될 수 있습니다. 저장 전 상태는 서버의 자동 스냅샷에 보관됩니다.</p><label class="sales-confirm"><input type="checkbox" id="sales-delete-confirm"> 위 월·매장·금액을 확인했으며 선택한 ERP 매출 삭제에 동의합니다.</label><p id="sales-delete-error" class="settings-error" role="alert"></p><div class="toolbar"><button id="sales-delete-commit" class="danger-button" disabled>확인한 매출 삭제</button><button id="sales-delete-cancel">취소</button></div></section>`;
}
function bindSalesDeletion(){
 const writable=['admin','editor'].includes(session.user.role);if(!writable)return;
 const refreshSelection=()=>{const button=$('#sales-delete-selected');button.textContent='선택 매출 삭제 ('+salesSelection.size+')';button.disabled=!salesSelection.size;const all=$('#sales-select-all'),visible=selectedSales();all.checked=visible.length>0&&visible.every(r=>salesSelection.has(r.id));all.indeterminate=salesSelection.size>0&&!all.checked;all.disabled=!visible.length;};
 document.querySelectorAll('[data-sales-select]').forEach(input=>input.onchange=()=>{if(input.checked)salesSelection.add(input.dataset.salesSelect);else salesSelection.delete(input.dataset.salesSelect);refreshSelection();});
 if($('#sales-select-all'))$('#sales-select-all').onchange=e=>{for(const row of selectedSales()){if(e.target.checked)salesSelection.add(row.id);else salesSelection.delete(row.id);}document.querySelectorAll('[data-sales-select]').forEach(input=>input.checked=salesSelection.has(input.dataset.salesSelect));refreshSelection();};
 const preview=ids=>{try{stagedSalesDelete=planSalesDeletion(ids,state);render();$('#sales-delete-preview').scrollIntoView({block:'nearest'});}catch(error){$('#sales-error').textContent=error.message;}};
 if($('#sales-delete-selected'))$('#sales-delete-selected').onclick=()=>preview([...salesSelection]);
 document.querySelectorAll('[data-sales-delete]').forEach(button=>button.onclick=()=>preview([button.dataset.salesDelete]));
 if($('#sales-delete-cancel'))$('#sales-delete-cancel').onclick=()=>{stagedSalesDelete=null;render();};
 if($('#sales-delete-confirm'))$('#sales-delete-confirm').onchange=e=>$('#sales-delete-commit').disabled=!e.target.checked;
 if($('#sales-delete-commit'))$('#sales-delete-commit').onclick=async e=>{if(!$('#sales-delete-confirm').checked)return;e.target.disabled=true;try{const next=applySalesDeletion(stagedSalesDelete,state);await saveNext(next);stagedSalesDelete=null;stagedSales=null;salesSelection.clear();updateMonths();render();toast('선택한 ERP 매출을 삭제했습니다.');}catch(error){$('#sales-delete-error').textContent=error.message;}};
 if($('#sales-select-all'))refreshSelection();
}

function salesSortHeader(key,label){const active=salesOptions.sortKey===key,direction=salesOptions.sortDirection;return `<th scope="col" aria-sort="${active?(direction==='asc'?'ascending':'descending'):'none'}"><button type="button" class="sales-sort-button" data-sales-sort="${key}" aria-label="${label} 정렬 전환">${label}<span aria-hidden="true">${active?(direction==='asc'?'↑':'↓'):'↕'}</span></button></th>`;}

function costTabsView(){return `<div class="cost-tabs" role="tablist" aria-label="비용 업무 구분">${Object.entries(costTabLabels).map(([key,label])=>`<button type="button" role="tab" id="cost-tab-${key}" aria-controls="cost-tab-panel" data-cost-tab="${key}" aria-selected="${costTab===key}" class="${costTab===key?'active':''}">${label}</button>`).join('')}</div>`;}
function bindCostTabs(){document.querySelectorAll('[data-cost-tab]').forEach(button=>button.onclick=()=>{if(button.dataset.costTab===costTab)return;if(stagedUpload&&!confirm('탭을 바꾸면 저장하지 않은 업로드 검토가 닫힙니다. 이동할까요?'))return;costTab=button.dataset.costTab;stagedUpload=null;render();});if($('#cost-tab-entry'))$('#cost-tab-entry').onclick=()=>{view={center:'entry',trade:'tradeEntry',common:'commonEntry'}[costTab];render();};}
